/// The settings connect/re-auth flow helpers (gh-1848 tier-3): part of
/// `settings.dart`'s library (gh-1232 god-file ceiling — the sweep's
/// extractions live here so the host file stays under the loc gate).
/// Extension members resolve statically inside the library, so the
/// callers in `settings.dart` are unchanged.
part of 'settings.dart';

/// Connect/re-auth/reset flow helpers of [_SettingsScreenState].
extension _SettingsFlowHelpers on _SettingsScreenState {
  /// The non-AIIN re-auth dispatch (gh-1848 tier-3 split): the Copilot
  /// connect flow for Copilot base URLs, the Codemie SSO flow otherwise.
  Future<bool> _reauthenticateOther(
    BuildContext context,
    ProviderRegistry registry,
    AgentService? service,
    CustomProvider provider,
  ) {
    if (isCopilotBaseUrl(provider.baseUrl)) {
      return runCopilotConnectFlow(
        context: context,
        registry: registry,
        service: service,
        lastConnectionStore: _fallbackConnectionStore(),
      );
    }
    return runCodemieSsoFlow(
      context: context,
      registry: registry,
      service: service,
      lastConnectionStore: _fallbackConnectionStore(),
      orgUrl: codeMieOrgUrl(provider.baseUrl),
    );
  }

  /// AIIN entries re-run the AIIN sign-in flow in re-auth mode
  /// (gh-1848 split).
  Future<bool> _reauthenticateAiin(
    BuildContext context,
    ProviderRegistry registry,
    AgentService? service,
    CustomProvider provider,
  ) {
    return runAiinConnectFlow(
      context: context,
      registry: registry,
      service: service,
      lastConnectionStore: _fallbackConnectionStore(),
      reauthenticateFor: provider,
    );
  }

  /// Runs one connect flow after a registry guard — the shared shape of
  /// the section's connect callbacks: a null registry renders the
  /// section but the flows do nothing (gh-1848 split).
  Future<void> _runConnectFlow(
    Future<void> Function(ProviderRegistry registry) run,
  ) async {
    final registry = widget.registry;
    if (registry == null) return;
    await run(registry);
  }
}

// Guardrails that keep the analytics layer wired and visible.
//
// 1. Every screen file (plus the shared composer and the JS-app surfaces)
//    carries at least one `AppAnalytics.instance.` call, or is listed in
//    `_documentedExemptions` with a reason — screens always carry
//    analytics, so user paths stay visible.
// 2. Every public event method on AppAnalytics is referenced at least once
//    in lib/ outside analytics.dart — no dead events accrete in the facade.
//
// Pure Dart (dart:io directory scan, no widget pumping): runs under both
// `dart test` and `flutter test`.

import 'dart:io';

import 'package:test/test.dart';

/// Tracked files that legitimately carry no AppAnalytics call, and why.
const _documentedExemptions = <String, String>{
  'lib/ui/screens/mobile_consent_screen.dart':
      'Accessibility consent surface (issue #622): a privacy-sensitive '
      'pre-permission screen — deliberately carries no analytics calls '
      'so nothing about a user\u0027s consent journey is tracked; the '
      'screen reconciles state locally via MobileControlContract.',
  'lib/ui/screens/onboarding_mockups.dart':
      'Part file of onboarding_screen.dart (pure mockup widgets); the '
      'onboarding analytics (started/completed/skipped/screenOpened) live '
      'in the main file.',
  'lib/ui/screens/codemie_sso_webview.dart':
      'Fallback-only WebView (the primary iOS SSO path is '
      'ASWebAuthenticationSession in codemie_sso_flow.dart, which carries '
      'the analytics); shown only when the system session cannot start — '
      'no meaningful user path to track.',
  'lib/ui/screens/codemie_sso_pickers.dart':
      'The informational project picker and the model quick-filter page '
      'extracted out of codemie_sso_flow.dart (issue #476) — the whole '
      'CodeMie SSO surface carries no AppAnalytics calls by design (see '
      'the codemie_sso_webview.dart exemption); the pickers fire no new '
      'user paths, only selection state for the calling flow.',
  'lib/ui/screens/settings_key_dialogs.dart':
      'Two modal key-management dialogs (edit one key, add a key) opened '
      'from the Keys section — the section carries the analytics events; '
      'the dialogs are pure text-entry forms with no actions of their own.',
  'lib/ui/widgets/chat_composer.dart':
      'Adapter shim — the composer lives in packages/fa_ui; messageSent/'
      'uploadAdded/voiceInputUsed fire via FaChatHost.track, routed into '
      'AppAnalytics by the FaChatHost.analytics hookup in main.dart.',
  'lib/ui/screens/chat_screen.dart':
      'Adapter shim — the screen lives in packages/fa_ui (FaChatScreen); '
      'screenOpened/filesOpened/settingsOpened fire via FaChatHost.track, '
      'routed into AppAnalytics by the FaChatHost.analytics hookup in '
      'main.dart.',
  'lib/ui/screens/media_slot_picker_page.dart':
      'Re-export shim — the page lives in packages/fa_ui; screenOpened is '
      'logged at the app-side push point (MediaModelsSection._editSlot).',
  'lib/ui/screens/provider_editor_page.dart':
      'Re-export shim — the page lives in packages/fa_ui; screenOpened is '
